// Тикет #6a86f7e8 F-95 (6a86f7e837c38d2b29bd68b9) AC3 — сбой шаринга. עבר QA 13.10.2026; проверено на web (expo.app) подменой navigator.share
// (скрин .qa/screenshots/6a86f7e8-web-share-failure-message.jpg): «הזמנת אדם להתחזק» → «המשך לשיתוף» → share падает →
// окно «הזמנת אדם להתחזק» с «השיתוף לא הצליח במכשיר הזה.» и «אישור»; карта «מפת השפעה» без изменений.
// В нативном приложении системный сбой шаринга не вызвать — там @manual-check (.qa/app-e2e/specs/auth-login/al-04).
import { test, expect } from '@playwright/test';
import * as path from 'path';
import { suppressMilestoneWindow, dismissMilestoneIfShown } from '../_helpers/milestone';

test.use({ storageState: path.resolve(__dirname, '../../../auth/user1.json') });

test.describe('«מפת השפעה» и приглашение', () => {
  test('IM-04 Сбой системного шаринга → «השיתוף לא הצליח במכשיר הזה.», «אישור» закрывает, «N אנשים» без изменений #6a86f7e8 @prod-safe', async ({ page }) => {
    await suppressMilestoneWindow(page);
    // 1. До перехода: navigator.share всегда падает (не AbortError — это не отмена пользователем), canShare = () => true.
    await page.addInitScript(() => {
      Object.defineProperty(navigator, 'share', {
        configurable: true,
        value: () => Promise.reject(new DOMException('QA-AUTO share failure', 'NotAllowedError')),
      });
      Object.defineProperty(navigator, 'canShare', { configurable: true, value: () => true });
    });

    // 2. `/journey` → счётчик «N אנשים» до.
    await page.goto('/journey');
    await expect(page.getByRole('heading', { name: 'מפת השפעה' })).toBeVisible({ timeout: 20_000 });
    await dismissMilestoneIfShown(page);
    const counter = page.getByText(/^\d+ אנשים$/);
    await expect(counter).toBeVisible();
    const before = (await counter.textContent())?.trim();

    // 3. «הזמנת אדם להתחזק» → «המשך לשיתוף» → сообщение о сбое.
    await page.getByRole('button', { name: 'הזמנת אדם להתחזק' }).click();
    await page.getByRole('dialog').getByRole('button', { name: 'המשך לשיתוף' }).click();
    const dialog = page.getByRole('dialog');
    await expect(dialog).toContainText('השיתוף לא הצליח במכשיר הזה.');
    await expect(dialog).toContainText('הזמנת אדם להתחזק');

    // 4. «אישור» закрывает окно; карта без изменений.
    await dialog.getByRole('button', { name: 'אישור' }).click();
    await expect(page.getByRole('dialog')).toHaveCount(0);
    await expect(counter).toHaveText(before ?? '');
  });
});
